/**
 * TypeScript Type Definitions for btp-guard (BTP v2.4)
 */

export interface VerificationResult {
  ok: boolean;
  msg: string;
}

export interface ScrubResult {
  data: any;
  redactionCount: number;
}

export interface BtpAttestation {
  protocol_version: string;
  authority: string;
  authority_pubkey: string;
  nonce: string;
  issued_at_unix: number;
  expires_at_unix: number;
  originating_agent: string;
  target_recipient: string;
  action_type: string;
  action_payload_hash: string;
  policy_id: string;
  policy_hash: string;
  capability_scope: string[];
  verdict: "ALLOW" | "DENY";
  reason: string;
  sandbox_receipt?: any;
  evaluation_latency_us?: number;
}

export interface BtpReceiptPacket {
  attestation: BtpAttestation;
  signature: string;
}

export interface BtpTurnReceipt {
  protocol: string;
  turn_index: number;
  parent_receipt_hash: string;
  receipt_hash: string;
  tool_name: string;
  action_payload_hash: string;
  scrubbed_secrets_count: number;
  transaction_state: "COMMITTED" | "ROLLED_BACK";
  timestamp_unix: number;
  authority_pubkey: string;
  signature: string;
}

/**
 * Encodes a JSON-serializable value into RFC 8785 canonical UTF-8 bytes.
 */
export function rfc8785Canonicalize(val: any): Buffer;

/**
 * 100% Offline independent BTP receipt verifier.
 */
export function verifyBtpReceipt(
  receiptPacket: BtpReceiptPacket | string,
  candidatePayload: any,
  trustedPubkeys: string | string[],
  expectedRecipient?: string,
  evalTimestamp?: number,
  requiredPolicyHash?: string,
  allowedCapabilities?: string[]
): VerificationResult;

/**
 * Verifies BTP v2.4 Chained Merkle Turn Receipt.
 */
export function verifyTurnReceiptChaining(
  parentReceiptHash: string,
  turnReceipt: BtpTurnReceipt | string,
  trustedPubkeys?: string | string[]
): VerificationResult;

/**
 * In-flight sensitive credential scrubber for Model Context Protocol payloads.
 */
export function scrubSensitiveCredentials(data: any): ScrubResult;

export interface IntentEvaluationInput {
  agentId?: string;
  actionType?: string;
  payload?: any;
  policy?: string;
}

export interface IntentEvaluationResult {
  allowed: boolean;
  latencyUs: number;
  reason: string;
  verdict: "ALLOW" | "DENY";
  payloadHash: string;
  scrubbedPayload: any;
  signature: string;
  attestation: BtpAttestation;
  authorityPubkey: string;
}

/**
 * Sub-35µs In-Process Intent & Tool Evaluation Gate
 */
export function evaluateIntent(intent?: IntentEvaluationInput): IntentEvaluationResult;

/**
 * Verifies an intent evaluation receipt generated by evaluateIntent.
 */
export function verifyReceipt(receipt: any): boolean;

/**
 * Emits clean, non-intrusive enterprise telemetry conversion hook.
 */
export function emitEnterpriseHook(workspaceId?: string): void;

/**
 * Emits conversion notice upon vetoed AST violation.
 */
export function emitVetoHook(command?: string, latencyUs?: number): void;

/**
 * Runs the formal conformance test suite.
 */
export function runNodeJsConformance(): boolean;


export interface ProtectAgentOptions {
  spendCap?: number;
  strict?: boolean;
  agentId?: string;
}

/**
 * Universal 1-line agent protector for Node.js / TypeScript agents.
 * Compatible with LangChain.js, Vercel AI SDK, Mastra, AutoGen JS, Claude SDK.
 */
export function protectAgent<T extends object>(agent: T, options?: ProtectAgentOptions): T;

export interface WorkspaceSecurityReport {
  score: number;
  grade: string;
  status: string;
  checks: Array<{ id: string; name: string; passed: boolean; pts: number }>;
  recommendations: Array<{ id: string; title: string; action: string }>;
}

export interface ImmunizeResult {
  status: string;
  workspacePath: string;
  changes: Array<{ file: string; action: string; desc: string }>;
  securityScore: number;
  grade: string;
}

/**
 * Audits the active workspace for deterministic AST safety invariants and AI companion rules.
 */
export function evaluateWorkspaceSecurity(workspaceRoot?: string): WorkspaceSecurityReport;

/**
 * Returns structured prompt briefing for AI models (Gemini, Claude, Cursor, Copilot).
 */
export function getModelContextPrompt(workspaceRoot?: string, modelTarget?: string): string;

/**
 * One-command project immunizer: generates AI guardrails (.cursorrules, CLAUDE.md, GEMINI.md)
 * and policy files for active workspace.
 */
export function immunizeProject(workspaceRoot?: string, options?: { force?: boolean }): ImmunizeResult;


export interface UniversalToolContract {
  name: string;
  category: "ast_firewall" | "secret_vault" | "keystone" | "universal_schema" | "compliance";
  desc: string;
  latency_us: number;
  scope: string;
  inputSchema: Record<string, any>;
  sourceFormat: string;
}

export interface PayloadValidationResult {
  valid: boolean;
  allowed: boolean;
  astVeto: boolean;
  reason: string;
  errors: string[];
  latency_us: number;
  redactionCount: number;
  sanitizedPayload: Record<string, any>;
}

export interface AuditDossier {
  "@context": string;
  type: string;
  protocol_version: string;
  audit_certificate_id: string;
  timestamp_utc: string;
  compliance_score: number;
  compliance_grade: string;
  auditor_authority: string;
  public_key_hex: string;
  frameworks: string[];
  controls_matrix: any[];
  benchmark_evidence: any;
  evidence_ledger: any[];
  merkle_tree_proof: {
    leaves_count: number;
    merkle_root: string;
    hash_algorithm: string;
    canonicalization: string;
  };
  content_digest_sha256: string;
  cryptographic_signature: string;
}

export interface AuditVerificationResult {
  ok: boolean;
  score?: number;
  grade?: string;
  protocol?: string;
  controls_verified?: number;
  merkle_root?: string;
  error?: string;
}

export function detectSchemaFormat(raw: any): string;
export function harmonizeUniversalSchema(raw: any, options?: any): UniversalToolContract;
export function harmonizeOpenApiSpec(spec: any, options?: any): UniversalToolContract[];
export function exportToolSchema(tool: any, targetFormat?: string): any;
export function validateToolPayload(toolOrSchema: any, payload?: any, options?: any): PayloadValidationResult;

export function computeMerkleRoot(leaves: any[]): string;
export function generateAuditPack(options?: any): AuditDossier;
export function verifyAuditPack(dossier: any): AuditVerificationResult;

export function guardUniversalAgentTool<T extends (...args: any[]) => any>(
  toolName: string,
  executeFn: T,
  options?: any
): (...args: Parameters<T>) => Promise<any>;

export function guardVercelAITool<T extends object>(toolDef: T, options?: any): T;
export function guardLangChainJsTool<T extends object>(toolInstance: T, options?: any): T;

export const BTP_CAPABILITY_MANIFEST: Record<string, any>;

export interface BoundaryAuditResult {
  audited_at: string;
  protocol_version: string;
  boundary_verdict: string;
  total_tools_audited: number;
  vulnerable_tools_count: number;
  findings: Array<{
    tool_name: string;
    category: string;
    risk_level: string;
    threats: string[];
    unshielded_boundary: boolean;
    recommended_guard: string;
    integration_recipe: Record<string, any>;
  }>;
  recommendation: string;
  audit_receipt: string;
  deterministic: boolean;
}

export interface EnforceBoundaryResult {
  allowed: boolean;
  verdict: "ALLOW" | "DENY" | "HOLD_FOR_APPROVAL";
  tool_name: string;
  rule_id?: string;
  reason?: string;
  remediation_hint?: string;
  safe_alternative?: string | null;
  approval_token?: string;
  merkle_turn_receipt?: string;
  latency_us: string;
  tool_input?: any;
}

export function auditToolBoundary(tools?: any[], options?: any): BoundaryAuditResult;
export function enforceToolBoundary(toolName: string, toolInput: any, options?: any): EnforceBoundaryResult;

export class MicrosoftAutoGenMiddleware {
  constructor(options?: any);
  processMessageBeforeSend(sender: any, recipient: any, message: any): {
    proceed: boolean;
    intercepted: boolean;
    message?: any;
    error?: string;
    verdict?: string;
    rule_id?: string;
    merkle_turn_receipt?: string;
  };
  interceptCodeExecution(code: string, language?: string, agentContext?: any): Promise<{
    exitCode: number;
    output?: string;
    allowed: boolean;
    verdict: string;
    rule_id?: string;
    merkle_turn_receipt?: string;
  }>;
  verifyGroupChatConsensus(speakers: any[], plannedAction: any): {
    consensusAllowed: boolean;
    verdict: string;
    receipt?: string;
  };
}

export class MicrosoftSemanticKernelMiddleware {
  constructor(options?: any);
  onFunctionInvocation(context: any, next?: (ctx: any) => Promise<any>): Promise<any>;
  onPromptRendering(context: any, next?: (ctx: any) => Promise<any>): Promise<any>;
}

export function createMicrosoftAutoGenHook(options?: any): {
  process_message_before_send: (sender: any, recipient: any, message: any) => any;
  intercept_code_execution: (code: string, lang?: string, ctx?: any) => Promise<any>;
  middleware: MicrosoftAutoGenMiddleware;
};

export function createMicrosoftSemanticKernelFilter(options?: any): {
  onFunctionInvocation: (ctx: any, next?: (ctx: any) => Promise<any>) => Promise<any>;
  onPromptRendering: (ctx: any, next?: (ctx: any) => Promise<any>) => Promise<any>;
  middleware: MicrosoftSemanticKernelMiddleware;
};

export class GoogleGenAIMiddleware {
  constructor(options?: any);
  interceptFunctionCall(functionCall: { name: string; args: any }, agentContext?: any): {
    allowed: boolean;
    verdict: string;
    rule_id?: string;
    reason?: string;
    merkle_turn_receipt?: string;
    error?: string;
    sanitizedArgs?: any;
  };
  wrapToolFunction<T extends (...args: any[]) => any>(toolFn: T, name?: string): (...args: Parameters<T>) => Promise<any>;
}

export class LlamaIndexMiddleware {
  constructor(options?: any);
  interceptWorkflowStep(stepName: string, stepInput: any): {
    proceed: boolean;
    verdict: string;
    rule_id?: string;
    reason?: string;
    merkle_turn_receipt?: string;
  };
  wrapTool<T extends object>(tool: T): T;
}

export function createGoogleGenAIMiddleware(options?: any): GoogleGenAIMiddleware;
export function createLlamaIndexWorkflowMiddleware(options?: any): LlamaIndexMiddleware;

export class ClaudeCodeAdapter {
  constructor(executor?: (toolName: string, input: any) => Promise<any> | any, options?: any);
  handleToolInvocation(toolName: string, toolInput?: any): Promise<{
    allowed: boolean;
    isError: boolean;
    verdict: string;
    rule_id?: string;
    reason?: string;
    merkle_turn_receipt?: string;
    sanitizedInput?: any;
    result?: any;
    error?: string;
    content?: string;
  }>;
}

export function createClaudeCodeHook(
  executor?: (toolName: string, input: any) => Promise<any> | any,
  options?: any
): (toolName: string, toolInput?: any) => Promise<any>;
